b=1.5
alpha=1.0
X=[[0.,1.],[q,0.],[q,0.]]
blocks=[(0,1),(0,2),(1,2)]
def F(Y):
 return b*(Y[1][1]-Y[2][1])+sum(abs(v) for row in Y for v in row)
f0=F(X)
for B in blocks:
 for branch in ['rotation','reflection']:
  best=(float('inf'),None)
  for j in range(20001):
   theta=2*math.pi*j/20000
   c,s=math.cos(theta),math.sin(theta)
   V=[[c,s],[-s,c]] if branch=='rotation' else [[-c,s],[s,c]]
   Y=[row[:] for row in X]
   for i in range(2):
    for l in range(2): Y[B[i]][l]=sum(V[i][m]*X[B[m]][l] for m in range(2))
   penalty=alpha/2*sum((V[i][j]-(i==j))**2 for i in range(2) for j in range(2))
   diff=F(Y)-f0+penalty
   if diff<best[0]: best=(diff,theta)
  print('Block',tuple(i+1 for i in B),branch,'minimum sampled surrogate change',best)
